#include <stdio.h>
#include <stdlib.h>

struct Account {
    char owner[32];
    long long balance;
};

struct Account *account_open(void) {
    struct Account *a = malloc(sizeof *a);
    if (a == NULL || scanf("%31s", a->owner) != 1) {
        free(a);
        return NULL;
    }
    a->balance = 0;
    return a;
}

void account_close(struct Account *a) {
    printf("closed %s\n", a->owner);
    free(a);
}

int main(void) {
    struct Account *a = account_open();
    if (a == NULL) {
        return 1;
    }
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        long long amount;
        scanf("%lld", &amount);
        a->balance += amount;
    }
    account_close(a);
    printf("balance=%lld\n", a->balance);
    return 0;
}

