#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *read_list(void) {
    struct Node *head = NULL, **tail = &head;
    int x;
    while (scanf("%d", &x) == 1) {
        struct Node *node = malloc(sizeof *node);
        if (node == NULL) {
            break;
        }
        node->value = x;
        node->next = NULL;
        *tail = node;
        tail = &node->next;
    }
    return head;
}

void free_list(struct Node *head) {
    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

int remove_negative(struct Node **head) {
    int removed = 0;
    struct Node *prev = NULL;
    for (struct Node *n = *head; n != NULL; n = n->next) {
        if (n->value < 0) {
            if (prev == NULL) {
                *head = n->next;
            } else {
                prev->next = n->next;
            }
            free(n);
            removed++;
        } else {
            prev = n;
        }
    }
    return removed;
}

int main(void) {
    struct Node *head = read_list();
    int removed = remove_negative(&head);
    for (struct Node *n = head; n != NULL; n = n->next) {
        printf("%d ", n->value);
    }
    printf("(removed %d)\n", removed);
    free_list(head);
    return 0;
}

