#include <stdio.h>
#include <stdlib.h>

struct Task {
    char name[24];
    int duration;
};

int main(void) {
    int n;
    scanf("%d", &n);
    struct Task *all[50] = {NULL};
    for (int i = 0; i < n; i++) {
        all[i] = malloc(sizeof *all[i]);
        if (all[i] == NULL) {
            return 1;
        }
        scanf("%23s %d", all[i]->name, &all[i]->duration);
    }
    struct Task *queue[50];
    int length;
    scanf("%d", &length);
    for (int i = 0; i < length; i++) {
        int id;
        scanf("%d", &id);
        queue[i] = all[id];
    }
    int c;
    scanf("%d", &c);
    for (int i = 0; i < c; i++) {
        int id;
        scanf("%d", &id);
        free(all[id]);
        all[id] = NULL;
    }

    int total = 0;
    for (int i = 0; i < length; i++) {
        if (queue[i] != NULL) {
            printf("%s ", queue[i]->name);
            total += queue[i]->duration;
        }
    }
    printf("total=%d\n", total);
    for (int i = 0; i < n; i++) {
        free(all[i]);
    }
    return 0;
}

