#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node {
    int value;
    struct Node *next;
};

int main(void) {
    struct Node *head = NULL;
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "print") == 0) {
            if (head == NULL) {
                printf("empty\n");
            }
            for (struct Node *n = head; n != NULL; n = n->next) {
                printf(n->next ? "%d " : "%d\n", n->value);
            }
            continue;
        }
        int x;
        scanf("%d", &x);
        struct Node **link = &head;
        if (strcmp(cmd, "add") == 0) {
            while (*link != NULL) {
                link = &(*link)->next;
            }
            struct Node *node = malloc(sizeof *node);
            if (node == NULL) {
                break;
            }
            node->value = x;
            node->next = NULL;
            *link = node;
        } else {
            int removed = 0;
            while (*link != NULL) {
                if ((*link)->value == x) {
                    struct Node *dead = *link;
                    *link = dead->next;
                    free(dead);
                    removed++;
                } else {
                    link = &(*link)->next;
                }
            }
            printf("%d\n", removed);
        }
    }
    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

